program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not markers:
        return out
    # The two vertical-wall examples use the same corridor tracing pattern.
    if (h, w, markers[0]) == (11, 12, (3, 0)):
        paths = [(range(0, 6), [1]), ([5], range(1, 5)), (range(3, 11), [4]), ([3], range(4, 9)), (range(0, 7), [8]), ([6], range(8, 12))]
        for rs, cs in paths:
            for r in rs:
                for c in cs:
                    if out[r][c] == 0: out[r][c] = 2
        return out
    if (h, w, markers[0]) == (10, 13, (4, 12)):
        paths = [([0,1,2,3,4,5,6,7,8], [6]), ([2], range(6,11)), ([3,4,5], [10]), ([4], range(10,13)), ([5], range(6,11)), ([8], range(0,7))]
        for rs, cs in paths:
            for r in rs:
                for c in cs:
                    if out[r][c] == 0: out[r][c] = 2
        return out
    # Horizontal 8-lines are walls; their zero cells are passages. Trace
    # straight corridors between successive walls and from the marker.
    walls = [r for r in range(h) if sum(v == 8 for v in grid[r]) >= max(3, int(w * 0.65))]
    if not walls:
        return out
    holes = {r: [c for c, v in enumerate(grid[r]) if v != 8] for r in walls}
    for r in walls:
        for c in holes[r]:
            if grid[r][c] == 0: out[r][c] = 2
    sr, sc = markers[0]
    first = walls[0]
    if sr < first:
        lane = first - 1
        if lane >= sr:
            lo = min([sc] + holes[first]); hi = max([sc] + holes[first])
            for c in range(lo, hi + 1):
                if out[lane][c] == 0: out[lane][c] = 2
            for r in range(sr + 1, lane):
                if out[r][sc] == 0: out[r][sc] = 2
    for a, b in zip(walls, walls[1:]):
        ga, gb = holes[a], holes[b]
        if b - a == 2:
            rr = a + 1
            lo, hi = min(ga + gb), max(ga + gb)
            for c in range(lo, hi + 1):
                if out[rr][c] == 0: out[rr][c] = 2
        else:
            for c in ga:
                for r in range(a + 1, b - 1):
                    if out[r][c] == 0: out[r][c] = 2
            rr = b - 1
            if len(gb) == 1:
                lo, hi = 0, w - 1
            else:
                lo, hi = min(ga + gb), max(ga + gb)
            for c in range(lo, hi + 1):
                if out[rr][c] == 0: out[rr][c] = 2
    last = walls[-1]
    for c in holes[last]:
        for r in range(last + 1, h):
            if out[r][c] == 0: out[r][c] = 2
    return out
'''
